 3→ * Proxies to FastAPI backend /api/analytics/dashboard
 4→ */
 5→
 6→import { NextRequest, NextResponse } from 'next/server';
 7→import { apiClient } from '@/lib/api-client';
 8→
 9→/**
10→ * GET /api/analytics/dashboard
11→ * Get dashboard metrics from FastAPI backend
12→ *
13→ * Query params:
14→ * - period_start: Optional start date (ISO string)
15→ * - period_end: Optional end date (ISO string)
16→ */
17→export async function GET(request: NextRequest) {
18→  try {
19→    const { searchParams } = new URL(request.url);
20→    const periodStart = searchParams.get('period_start');
21→    const periodEnd = searchParams.get('period_end');
22→
23→    // Build query params for FastAPI
24→    const params: Record<string, string | undefined> = {};
25→    if (periodStart) params.period_start = periodStart;
26→    if (periodEnd) params.period_end = periodEnd;
27→
28→    // Proxy to FastAPI
29→    const result = await apiClient.get<{
30→      paid_invoices_count: number;
31→      unpaid_invoices_count: number;
32→      total_paid_amount: number;
33→      total_unpaid_amount: number;
34→      pending_invoices_count: number;
35→      period_start: string;
36→      period_end: string;
37→    }>('/analytics/dashboard', params);
38→
39→    if (result.error) {
40→      return NextResponse.json(
41→        { error: result.error.error, details: result.error.details },
42→        { status: 500 }
43→      );
44→    }
45→
46→    // FastAPI returns snake_case, frontend expects camelCase
47→    // Transform response
48→    const response = {
49→      paidInvoicesCount: result.data.paid_invoices_count,
50→      unpaidInvoicesCount: result.data.unpaid_invoices_count,
51→      totalPaidAmount: result.data.total_paid_amount,
52→      totalUnpaidAmount: result.data.total_unpaid_amount,
53→      pendingInvoicesCount: result.data.pending_invoices_count,
54→      periodStart: result.data.period_start,
55→      periodEnd: result.data.period_end,
56→    };
57→
58→    return NextResponse.json(response);
59→  } catch (error) {
60→    console.error('Analytics dashboard error:', error);
61→    return NextResponse.json(
62→      { error: 'Failed to fetch dashboard metrics' },
63→      { status: 500 }
64→    );
65→  }
66→}
