 1→/**
 2→ * Analytics Payment Dynamics API Route
 3→ * Proxies to FastAPI backend /api/analytics/payment-dynamics
 4→ */
 5→
 6→import { NextRequest, NextResponse } from 'next/server';
 7→import { apiClient } from '@/lib/api-client';
 8→
 9→/**
10→ * GET /api/analytics/payment-dynamics
11→ * Get payment dynamics time series data from FastAPI backend
12→ *
13→ * Query params:
14→ * - period_start: Optional start date (ISO string)
15→ * - period_end: Optional end date (ISO string)
16→ * - group_by: Grouping period - 'day', 'week', or 'month' (default: 'day')
17→ */
18→export async function GET(request: NextRequest) {
19→  try {
20→    const { searchParams } = new URL(request.url);
21→    const periodStart = searchParams.get('period_start');
22→    const periodEnd = searchParams.get('period_end');
23→    const groupBy = searchParams.get('group_by') || 'day';
24→
25→    // Build query params for FastAPI
26→    const params: Record<string, string> = {
27→      group_by: groupBy,
28→    };
29→    if (periodStart) params.period_start = periodStart;
30→    if (periodEnd) params.period_end = periodEnd;
31→
32→    // Proxy to FastAPI
33→    const result = await apiClient.get<{
34→      data: Array<{
35→        date: string;
36→        paid_amount: number;
37→        paid_count: number;
38→      }>;
39→      total_amount: number;
40→      total_count: number;
41→      period_start: string;
42→      period_end: string;
43→    }>('/analytics/payment-dynamics', params);
44→
45→    if (result.error) {
46→      return NextResponse.json(
47→        { error: result.error.error, details: result.error.details },
48→        { status: 500 }
49→      );
50→    }
51→
52→    // FastAPI returns snake_case, transform to camelCase for frontend
53→    const response = {
54→      data: result.data.data.map((point) => ({
55→        date: point.date,
56→        paidAmount: point.paid_amount,
57→        paidCount: point.paid_count,
58→      })),
59→      totalAmount: result.data.total_amount,
60→      totalCount: result.data.total_count,
61→      periodStart: result.data.period_start,
62→      periodEnd: result.data.period_end,
63→    };
64→
65→    return NextResponse.json(response);
66→  } catch (error) {
67→    console.error('Analytics payment-dynamics error:', error);
68→    return NextResponse.json(
69→      { error: 'Failed to fetch payment dynamics' },
70→      { status: 500 }
71→    );
72→  }
73→}
